'use client'

import { clubThemeCss } from '@/lib/brand/colour'
import { useCallback, useState } from 'react'
import Link from 'next/link'
import { createClient } from '@/lib/supabase/client'
import { LadderBreakdownSheet, type Breakdown } from '@/components/ladder-breakdown'
import { SponsorStrip, type PublicSponsor } from './sponsor-strip'

export type Fixture = {
  id: string
  home_entry_id: string | null
  away_entry_id: string | null
  starts_at: string | null
  round: string | null
  division: string | null
  group_label: string | null
  venue: string | null
  field: string | null
  home: string | null
  away: string | null
  home_score: number | null
  away_score: number | null
  status: string
}

export type LadderRow = {
  entry_id: string
  team_name: string
  group_label: string | null
  played: number
  won: number
  drawn: number
  lost: number
  goals_for: number
  goals_against: number
  goal_difference: number
  points: number
}

export type SquadPlayer = { name: string; number: number | null }

/** 0266: a club in the competition, with the door to its own public page. */
export type PublicClub = { name: string; slug: string; suburb: string | null; logo_url: string | null }

export type Centre = {
  competition: { name: string; season: string | null; organiser: string }
  fixtures: Fixture[]
  ladder: Record<string, LadderRow[]>
  divisions: string[]
  /**
   * Team sheets, keyed by competition entry. Absent for a club that is only a
   * name on the draw, and absent for any club whose own academy has not opted
   * into publishing names — each player's own academy decides, never the
   * organiser's.
   */
  squads?: Record<string, SquadPlayer[]>
  /** L-12: goals from the sheets, named by each player's own club's rule. Absent for hidden-score divisions. */
  top_scorers?: Record<string, { name: string; team: string; goals: number }[]>
  /** L-16: teams may ask to enter from /c/[slug]/enter. */
  entries_open?: boolean
}

const SYDNEY = 'Australia/Sydney'

// A `const` assertion cannot be applied to a conditional expression, so the
// list is declared once and filtered rather than built inline.
const TABS = ['fixtures', 'ladder', 'scorers', 'squads'] as const
type Tab = (typeof TABS)[number]

/**
 * The public page.
 *
 * Written for a child on a phone, standing up, who wants one of two things:
 * when is my next game, and did we win. So those are the two tabs, and
 * Results opens on the most recent weekend rather than the first one of the
 * season — a season's draw read from the top is forty games of history
 * before you reach today.
 *
 * Nothing here is interactive beyond choosing what to look at. There is no
 * sign-in prompt, nothing to tap that asks who you are, and no analytics.
 */
/** The competition's slug, from the canonical page URL. */
function slugOf(shareUrl: string) {
  const parts = shareUrl.split('/c/')
  return parts[1] ?? ''
}

export function MatchCentre({
  centre,
  embed = false,
  initialTab,
  initialDivision,
  shareUrl,
  sponsors = [],
  switches,
  brand = null,
  clubs = [],
}: {
  centre: Centre
  /** 0266: the clubs in this competition, each a door to its own page. */
  clubs?: PublicClub[]
  /** The organiser's colours and logo (a league, usually). Null: black and white. */
  brand?: { primary: string | null; secondary: string | null; logo: string | null } | null
  /** L-12: inside a league's own website. No header, a footer link out. */
  embed?: boolean
  initialTab?: string
  initialDivision?: string
  /** The canonical page, for the Share button and the embed's footer. */
  shareUrl?: string
  /** X-08: the organiser's sponsors for the strip under the header. */
  sponsors?: PublicSponsor[]
  /** 0260: the organiser's switches — the ladder breakdown's tap shows only when on. */
  switches?: { ladder_breakdown?: boolean }
}) {
  const { competition, fixtures, ladder, divisions } = centre
  const slug = slugOf(shareUrl ?? '')
  const [division, setDivision] = useState(initialDivision && divisions.includes(initialDivision) ? initialDivision : divisions[0] ?? '')
  const [tab, setTab] = useState<Tab>((TABS as readonly string[]).includes(initialTab ?? '') ? (initialTab as Tab) : 'fixtures')

  const mine = divisions.length > 1 ? fixtures.filter((f) => f.division === division) : fixtures
  // Only offered when there is something to show. A Squads tab that opens on
  // "no squads published" is worse than no tab.
  const hasSquads = Object.keys(centre.squads ?? {}).length > 0
  const hasScorers = Object.values(centre.top_scorers ?? {}).some((l) => l.length > 0)

  // The organiser's colours on this page only, light and dark (lib/brand/colour).
  const brandCss = brand?.primary ? clubThemeCss(brand.primary, brand.secondary, '[data-club-scope]') : ''

  return (
    <main className={`mx-auto w-full max-w-lg ${embed ? 'pb-4' : 'pb-12'}`} data-club-scope>
      {brandCss && <style>{brandCss}</style>}
      {!embed && (
        <header
          className="px-5 pb-5 pt-7"
          style={{ background: 'var(--bar)', color: 'var(--bar-ink)' }}
        >
          <div className="flex items-center gap-2">
            {brand?.logo && (
              // eslint-disable-next-line @next/next/no-img-element -- the organiser's own file
              <img src={brand.logo} alt="" className="h-8 w-8 flex-none rounded-lg bg-white object-contain p-0.5" data-club-logo />
            )}
            <p className="eyebrow" style={{ color: 'inherit', opacity: 0.75 }}>
              Run by {competition.organiser}
            </p>
          </div>
          <h1 className="display mt-1 text-[1.875rem] leading-none">{competition.name}</h1>
          <div className="mt-1.5 flex items-center gap-3">
            {competition.season && (
              <p className="text-sm" style={{ opacity: 0.75 }}>
                {competition.season}
              </p>
            )}
            {shareUrl && <ShareButton title={competition.name} url={shareUrl} />}
          </div>
          {centre.entries_open && shareUrl && (
            <a href={`/c/${slug}/enter`} className="mt-3 inline-block rounded-full px-3.5 py-1.5 text-sm font-semibold" style={{ background: 'var(--bar-ink)', color: 'var(--bar)' }}>
              Enter a team ›
            </a>
          )}
        </header>
      )}

      {/* X-08: the organiser's sponsors — a name, a logo, a link. */}
      <SponsorStrip sponsors={sponsors} slug={slug} />

      {/* 0266: the clubs in this competition, each a door to its own page. */}
      {!embed && clubs.length > 0 && (
        <section className="px-3.5 pt-3" data-public-clubs={clubs.length}>
          <p className="eyebrow px-1">Clubs</p>
          <div className="mt-1.5 flex gap-2 overflow-x-auto pb-1">
            {clubs.map((c) => (
              <a key={c.slug} href={`/${c.slug}`} className="flex flex-none items-center gap-2 rounded-full border px-3 py-1.5 text-sm" style={{ borderColor: 'var(--line)' }}>
                {c.logo_url && (
                  // eslint-disable-next-line @next/next/no-img-element -- the club's own file
                  <img src={c.logo_url} alt="" className="h-5 w-5 rounded object-contain" />
                )}
                <span className="whitespace-nowrap">{c.name}</span>
              </a>
            ))}
          </div>
        </section>
      )}

      {divisions.length > 1 && (
        <div className="flex gap-1.5 overflow-x-auto px-3.5 pt-3.5 pb-1">
          {divisions.map((d) => (
            <button
              key={d}
              onClick={() => setDivision(d)}
              className="flex-none rounded-full px-3.5 py-1.5 text-sm font-semibold"
              style={
                division === d
                  ? { background: 'var(--brand)', color: 'var(--brand-ink)' }
                  : { background: 'var(--surface-2)', color: 'var(--ink-2)' }
              }
            >
              {d}
            </button>
          ))}
        </div>
      )}

      {/* Equal widths on one line; two lines when larger text no longer fits them (X-10). */}
      <div className="flex flex-wrap gap-1.5 px-3.5 py-2.5">
        {TABS.filter((t) => (t !== 'squads' || hasSquads) && (t !== 'scorers' || hasScorers)).map((t) => (
          <button
            key={t}
            onClick={() => setTab(t)}
            className="min-w-fit flex-1 rounded-xl px-3 py-2 text-sm font-semibold"
            style={
              tab === t
                ? { background: 'var(--surface-2)', color: 'var(--ink)' }
                : { background: 'transparent', color: 'var(--ink-3)' }
            }
          >
            {t === 'fixtures' ? 'Fixtures' : t === 'ladder' ? 'Ladder' : t === 'scorers' ? 'Scorers' : 'Squads'}
          </button>
        ))}
      </div>

      {tab === 'fixtures' ? (
        <Fixtures fixtures={mine} />
      ) : tab === 'scorers' ? (
        <Scorers rows={centre.top_scorers?.[division] ?? centre.top_scorers?.[divisions[0] ?? ''] ?? []} />
      ) : tab === 'ladder' ? (
        <Ladder rows={ladder[division] ?? ladder[divisions[0] ?? ''] ?? []} slug={slug} breakdown={Boolean(switches?.ladder_breakdown)} />
      ) : (
        <Squads
          squads={centre.squads ?? {}}
          entries={entriesIn(mine)}
        />
      )}

      <p className="px-6 pt-6 text-center text-xs text-ink-3">
        {hasSquads
          ? 'Squads are published by each club. Any family can ask to be left off.'
          : 'Clubs and scores only. No player names are published here.'}{' '}
        <Link href="/privacy" className="underline underline-offset-2">How we look after your info ›</Link>
      </p>
      {embed && shareUrl && (
        <p className="px-6 pt-2 text-center text-xs text-ink-3">
          <a href={shareUrl} target="_blank" rel="noreferrer" className="underline underline-offset-2">
            {competition.name} on Squadroom ›
          </a>
        </p>
      )}
    </main>
  )
}

/**
 * The phone's own share sheet where there is one (every phone), copy
 * where there is not. No tracking parameters on the link: the URL a child
 * pastes into a group chat is the same one everybody else has.
 */
function ShareButton({ title, url }: { title: string; url: string }) {
  const [copied, setCopied] = useState(false)
  async function share() {
    try {
      if (typeof navigator !== 'undefined' && navigator.share) {
        await navigator.share({ title, url })
        return
      }
      await navigator.clipboard.writeText(url)
      setCopied(true)
      setTimeout(() => setCopied(false), 1800)
    } catch {
      // Dismissed, or no clipboard. Nothing to report.
    }
  }
  return (
    <button
      onClick={() => void share()}
      className="ml-auto flex-none rounded-full px-3 py-1 text-xs font-semibold"
      style={{ background: 'color-mix(in srgb, var(--bar-ink) 14%, transparent)', color: 'var(--bar-ink)' }}
      aria-label="Share this page"
    >
      {copied ? 'Link copied' : 'Share'}
    </button>
  )
}

/**
 * Which clubs are in view, and what they are called.
 *
 * The squads come back keyed by competition entry id, and the fixtures are
 * where those ids are paired with club names — so the division filter the
 * reader already chose decides which squads they see, without a second
 * lookup.
 */
function entriesIn(fixtures: Fixture[]) {
  const seen = new Map<string, string>()
  for (const f of fixtures) {
    if (f.home_entry_id && f.home) seen.set(f.home_entry_id, f.home)
    if (f.away_entry_id && f.away) seen.set(f.away_entry_id, f.away)
  }
  return [...seen.entries()]
    .map(([id, name]) => ({ id, name }))
    .sort((a, b) => a.name.localeCompare(b.name))
}

function Squads({
  squads,
  entries,
}: {
  squads: Record<string, SquadPlayer[]>
  entries: { id: string; name: string }[]
}) {
  const withSquads = entries.filter((e) => (squads[e.id] ?? []).length > 0)

  if (withSquads.length === 0) {
    return <Empty>No squads published for this division yet.</Empty>
  }

  return (
    <div className="px-3.5">
      {withSquads.map((e) => {
        const players = squads[e.id]
        return (
          <section key={e.id} className="mb-4">
            <h3 className="eyebrow px-1 pb-1.5">
              {e.name} · {players.length}
            </h3>
            <div className="card overflow-hidden">
              {players.map((p, i) => (
                <div
                  key={`${e.id}-${i}`}
                  className="flex items-center gap-3 border-t px-3.5 py-2.5 text-sm first:border-t-0"
                  style={{ borderColor: 'var(--line-2)' }}
                >
                  {/* The number gets its own column even when unset, so the
                      names stay on one left edge down the list. */}
                  <span
                    className="w-6 flex-none text-right text-xs tabular-nums"
                    style={{ color: 'var(--ink-3)' }}
                  >
                    {p.number ?? ''}
                  </span>
                  <span className="min-w-0 flex-1 truncate">{p.name}</span>
                </div>
              ))}
            </div>
          </section>
        )
      })}
    </div>
  )
}

function Fixtures({ fixtures }: { fixtures: Fixture[] }) {
  if (fixtures.length === 0) {
    return <Empty>No draw published yet.</Empty>
  }

  // Grouped the way the competition is actually read: by round when it runs
  // over weeks, by kick-off time when it is one day. Same reasoning as the
  // organiser's run sheet — ten Sundays all headed "9:00 am" distinguishes
  // nothing, and a gala day grouped by round hides which field to walk to.
  const days = new Set(
    fixtures.filter((f) => f.starts_at).map((f) => dayKey(f.starts_at as string))
  )
  const byRound = days.size > 1

  const groups = new Map<string, Fixture[]>()
  for (const f of fixtures) {
    const key = byRound ? (f.round ?? 'Not scheduled') : (f.starts_at ?? 'unscheduled')
    groups.set(key, [...(groups.get(key) ?? []), f])
  }

  const sections = [...groups.entries()]

  // Open on the round nearest today, not on Round 1. A season read from the
  // top is forty games of history before you reach this weekend, and the
  // person opening this page on a Saturday wants today.
  const todayKey = dayKey(new Date().toISOString())
  const current = Math.max(
    0,
    sections.findIndex(([, games]) =>
      games.some((g) => g.starts_at && dayKey(g.starts_at) >= todayKey)
    )
  )

  return (
    <div>
      {sections.map(([label, games], i) => (
        <section key={label} id={i === current ? 'now' : undefined}>
          <h2 className="sticky top-0 flex items-baseline gap-2 border-b px-4 py-2 text-xs font-semibold uppercase tracking-wide backdrop-blur"
              style={{
                background: 'color-mix(in srgb, var(--surface-3) 94%, transparent)',
                borderColor: 'var(--line-2)',
                color: 'var(--ink-2)',
              }}>
            {byRound ? (
              <>
                <span>{label}</span>
                <span className="font-normal normal-case tracking-normal text-ink-3">
                  {dayOf(games)}
                </span>
              </>
            ) : (
              <span>{label === 'unscheduled' ? 'Not scheduled' : clock(label)}</span>
            )}
          </h2>

          {games.map((f) => {
            const played = f.status === 'final' && f.home_score !== null
            const homeWon = played && (f.home_score ?? 0) > (f.away_score ?? 0)
            const awayWon = played && (f.away_score ?? 0) > (f.home_score ?? 0)
            return (
              <div
                key={f.id}
                className="flex items-center gap-2.5 border-b px-4 py-3"
                style={{ borderColor: 'var(--line-2)' }}
              >
                <span className="w-12 flex-none text-xs tabular-nums text-ink-3">
                  {byRound ? (f.starts_at ? clock(f.starts_at) : '') : (f.field ?? '')}
                </span>

                <span className="min-w-0 flex-1 text-sm leading-snug">
                  <span className={homeWon ? 'font-semibold' : ''}>{f.home ?? 'TBC'}</span>
                  <span className="text-ink-3"> v </span>
                  <span className={awayWon ? 'font-semibold' : ''}>{f.away ?? 'TBC'}</span>
                  {(f.venue || (byRound && f.field)) && (
                    <span className="mt-0.5 block truncate text-xs text-ink-3">
                      {[f.venue, byRound ? f.field : null].filter(Boolean).join(' · ')}
                    </span>
                  )}
                </span>

                {played ? (
                  <span
                    className="flex-none text-sm font-bold tabular-nums"
                    style={{ color: 'var(--brand-text)' }}
                  >
                    {f.home_score}–{f.away_score}
                  </span>
                ) : (
                  <span className="flex-none text-xs text-ink-3">
                    {f.starts_at && !byRound ? '' : 'to play'}
                  </span>
                )}
              </div>
            )
          })}
        </section>
      ))}
    </div>
  )
}

function Ladder({ rows, slug, breakdown }: { rows: LadderRow[]; slug: string; breakdown: boolean }) {
  // 0260: tap a row, see every point. Fetched on the tap through the public
  // door (teams and scores only), by the same anon client the page uses.
  const [open, setOpen] = useState<LadderRow | null>(null)
  const fetchBreakdown = useCallback(async () => {
    if (!open) return null
    const { data } = await createClient().rpc('public_ladder_breakdown', { p_slug: slug, p_entry: open.entry_id })
    return (data as unknown as Breakdown | null) ?? null
  }, [slug, open])

  if (rows.length === 0) {
    return <Empty>No ladder yet — it appears once results are in.</Empty>
  }

  // Groups within a division get their own table, because a combined one
  // ordered by points is not a ladder anybody recognises.
  const groups = new Map<string, LadderRow[]>()
  for (const r of rows) groups.set(r.group_label ?? '', [...(groups.get(r.group_label ?? '') ?? []), r])

  return (
    <div className="px-3.5">
      {open && <LadderBreakdownSheet teamName={open.team_name} fetchBreakdown={fetchBreakdown} onClose={() => setOpen(null)} />}
      {[...groups.entries()].map(([group, table]) => (
        <div key={group} className="mb-4">
          {group && <h3 className="eyebrow px-1 pb-1.5">Group {group}</h3>}
          <div className="card overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="text-xs text-ink-3">
                  <th className="px-3 py-2 text-left font-semibold">Team</th>
                  <th className="px-1.5 py-2 text-right font-semibold">P</th>
                  <th className="px-1.5 py-2 text-right font-semibold">W</th>
                  <th className="px-1.5 py-2 text-right font-semibold">D</th>
                  <th className="px-1.5 py-2 text-right font-semibold">L</th>
                  {/* Goal difference earns its column; goals for and against
                      do not, at this width. */}
                  <th className="px-1.5 py-2 text-right font-semibold">GD</th>
                  <th className="px-3 py-2 text-right font-semibold">Pts</th>
                </tr>
              </thead>
              <tbody>
                {table.map((r, i) => (
                  <tr key={r.entry_id} className="border-t" style={{ borderColor: 'var(--line-2)' }} data-ladder-row={r.entry_id}>
                    <td className="px-3 py-2.5">
                      <span className="mr-2 tabular-nums text-ink-3">{i + 1}</span>
                      {breakdown ? (
                        <button onClick={() => setOpen(r)} className="tap text-left underline decoration-dotted underline-offset-4" data-ladder-breakdown-open={r.entry_id}>{r.team_name}</button>
                      ) : r.team_name}
                    </td>
                    <td className="px-1.5 py-2.5 text-right tabular-nums text-ink-2">{r.played}</td>
                    <td className="px-1.5 py-2.5 text-right tabular-nums text-ink-2">{r.won}</td>
                    <td className="px-1.5 py-2.5 text-right tabular-nums text-ink-2">{r.drawn}</td>
                    <td className="px-1.5 py-2.5 text-right tabular-nums text-ink-2">{r.lost}</td>
                    <td className="px-1.5 py-2.5 text-right tabular-nums text-ink-2">
                      {r.goal_difference > 0 ? `+${r.goal_difference}` : r.goal_difference}
                    </td>
                    <td className="px-3 py-2.5 text-right font-bold tabular-nums">{r.points}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      ))}
      {/* Said plainly, because the organiser's spreadsheet did the same and
          people asked about it every year. */}
      <p className="px-1 pt-1 text-xs text-ink-3">
        3 points for a win, 1 for a draw. Separated by goal difference, then goals scored. Teams
        level after that are shown level for the organiser to rule on.
      </p>
    </div>
  )
}

function Empty({ children }: { children: React.ReactNode }) {
  return (
    <p
      className="m-4 rounded-xl p-6 text-center text-sm text-ink-2"
      style={{ background: 'var(--surface-2)' }}
    >
      {children}
    </p>
  )
}

/** The calendar date in Sydney, for comparing one day to another. */
function dayKey(iso: string) {
  return new Date(iso).toLocaleDateString('en-CA', { timeZone: SYDNEY })
}

function clock(iso: string) {
  return new Date(iso)
    .toLocaleTimeString('en-AU', { hour: 'numeric', minute: '2-digit', timeZone: SYDNEY })
    .replace(' ', '')
    .toLowerCase()
}

/** "Sun 30 Aug" — the weekend a round is played on. */
function dayOf(games: Fixture[]) {
  const when = games.find((g) => g.starts_at)?.starts_at
  if (!when) return ''
  return new Date(when).toLocaleDateString('en-AU', {
    weekday: 'short',
    day: 'numeric',
    month: 'short',
    timeZone: SYDNEY,
  })
}

/** L-12: who scored, from the sheets. Named by each player's own club's rule. */
function Scorers({ rows }: { rows: { name: string; team: string; goals: number }[] }) {
  if (rows.length === 0) {
    return <p className="m-5 rounded-xl bg-[var(--surface-2)] p-5 text-center text-sm text-ink-2">No goals recorded yet.</p>
  }
  return (
    <ol className="px-4 py-2">
      {rows.map((r, i) => (
        <li key={i} className="flex items-center gap-3 border-b py-2.5 text-sm" style={{ borderColor: 'var(--line-2)' }}>
          <span className="w-5 flex-none text-right text-xs tabular-nums text-ink-3">{i + 1}</span>
          <span className="min-w-0 flex-1">
            <span className="block truncate font-medium">{r.name}</span>
            <span className="block truncate text-xs text-ink-3">{r.team}</span>
          </span>
          <span className="flex-none text-base font-bold tabular-nums" style={{ color: 'var(--brand-text)' }}>{r.goals}</span>
        </li>
      ))}
    </ol>
  )
}
